def subtract(a, b):
    # Filter out empty intervals and sort
    a = sorted([interval for interval in a if interval[0] < interval[1]])
    b = sorted([interval for interval in b if interval[0] < interval[1]])

    if not a:
        return []

    # Merge overlapping/touching intervals in b
    merged_b = []
    for start, end in b:
        if merged_b and start <= merged_b[-1][1]:
            merged_b[-1][1] = max(merged_b[-1][1], end)
        else:
            merged_b.append([start, end])

    # Merge overlapping/touching intervals in a
    merged_a = []
    for start, end in a:
        if merged_a and start <= merged_a[-1][1]:
            merged_a[-1][1] = max(merged_a[-1][1], end)
        else:
            merged_a.append([start, end])

    result = []

    for a_start, a_end in merged_a:
        current_start = a_start

        for b_start, b_end in merged_b:
            # b interval is completely after current segment
            if b_start >= a_end:
                break

            # b interval is completely before current segment
            if b_end <= current_start:
                continue

            # b interval overlaps with current segment
            if b_start > current_start:
                # Add the part before b
                result.append([current_start, b_start])

            # Move current_start past the b interval
            current_start = max(current_start, b_end)

        # Add any remaining part after all b intervals
        if current_start < a_end:
            result.append([current_start, a_end])

    # Merge touching intervals in result
    if not result:
        return []

    merged_result = [result[0]]
    for start, end in result[1:]:
        if start <= merged_result[-1][1]:
            merged_result[-1][1] = max(merged_result[-1][1], end)
        else:
            merged_result.append([start, end])

    return merged_result

